"""Write a self-contained interactive review with embedded diagnostic images."""
import argparse,base64,json
from pathlib import Path

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('out',type=Path);a=ap.parse_args();out=a.out;views={}
    pairs=[('Whole Base · front oblique','whole-{}-e15-a60'),('Whole Base · rear','whole-{}-e15-a180'),('Whole Base · top','whole-{}-top'),('Whole Base · underside','whole-{}-bottom'),('Housing only','member-4527988-{}-oblique'),('Housing reverse','member-4527988-{}-reverse'),('Tall cover A','member-4392221-{}-oblique'),('Module front','member-4121375-{}-oblique'),('Module backing','member-4723785-{}-reverse'),('Upper shell','member-4764759-{}-oblique')]
    for name,pattern in pairs:
        views[name]={stage:'data:image/png;base64,'+base64.b64encode((out/(pattern.format(stage)+'.png')).read_bytes()).decode() for stage in ('before','after')}
    html='''<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><style>
body{font-family:var(--font-sans),sans-serif;color:var(--foreground);margin:0}h2{font-size:22px;margin:0 0 14px}.stats{display:flex;gap:24px;flex-wrap:wrap;margin-bottom:14px}.stats strong{display:block;font-size:24px}.stats span,p{font-size:13px;color:var(--muted-foreground)}select,button{font:inherit;padding:7px 11px;border:1px solid var(--border);border-radius:6px;background:var(--card);color:var(--foreground)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}button.active{background:var(--primary);color:var(--primary-foreground)}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair img{width:100%;border-radius:7px}.label{font-size:12px;margin-bottom:6px}p{line-height:1.55}.detail{padding:14px 16px;background:var(--muted);border-radius:8px;margin-top:12px}.detail p{margin:0} @media(max-width:480px){.stats{gap:12px}.stats strong{font-size:21px}}
</style></head><body><h2>A more aggressive Base candidate</h2><div class="stats"><div><strong>82,414</strong><span>visual triangles · 25% fewer</span></div><div><strong>9,064</strong><span>housing · 43% fewer</span></div><div><strong>6.41 MB</strong><span>GLB · previously 8.46 MB</span></div></div><nav><select id="view" aria-label="Comparison view"></select><button id="both" class="active">Side by side</button><button id="before">Approved</button><button id="after">Candidate</button></nav><div class="pair" id="pair"><div id="left"><div class="label">Approved · 109,860 triangles</div><img id="a" alt="Approved Base diagnostic"></div><div id="right"><div class="label">Candidate · 82,414 triangles</div><img id="b" alt="Aggressive Base diagnostic"></div></div><div class="detail"><p><b>14 members simplified.</b> All 2,822 light triangles retain exact positions, normals and materials. 326 unchanged members include the approved crossbar. Collision stays at 16,857 triangles per Base.</p></div><p>Deliberately larger detail allowance: 1 mm nominal / 3 mm sampled, with native outline-corner locks. This is approximate visual LOD. Eighteen assembled views show at most 0.12% silhouette-mask difference. Substantial red LED views differ by at most 0.31%; the underside’s tiny LED slivers change more. Fixed-pose diagnostic rendering, not runtime PBR. Source CAD and installed field are unchanged.</p><script>const views=DATA;const select=document.getElementById('view');for(const name of Object.keys(views))select.add(new Option(name,name));function update(){document.getElementById('a').src=views[select.value].before;document.getElementById('b').src=views[select.value].after;}select.onchange=update;for(const mode of ['both','before','after'])document.getElementById(mode).onclick=()=>{for(const x of ['both','before','after'])document.getElementById(x).classList.toggle('active',x===mode);document.getElementById('left').style.display=mode==='after'?'none':'';document.getElementById('right').style.display=mode==='before'?'none':'';document.getElementById('pair').style.gridTemplateColumns=mode==='both'?'1fr 1fr':'1fr';};update();</script></body></html>'''.replace('DATA',json.dumps(views));(out/'review.html').write_text(html);print(out/'review.html')
if __name__=='__main__':main()
